CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('superadmin','admin','technician')));
CREATE TABLE IF NOT EXISTS clients (id SERIAL PRIMARY KEY, name TEXT NOT NULL, contact TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS client_access (client_id INTEGER REFERENCES clients ON DELETE CASCADE, user_id INTEGER REFERENCES users ON DELETE CASCADE, PRIMARY KEY(client_id,user_id));
CREATE TABLE IF NOT EXISTS sites (id SERIAL PRIMARY KEY, client_id INTEGER NOT NULL REFERENCES clients, name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS sites_client_idx ON sites(client_id);
CREATE TABLE IF NOT EXISTS plans (id SERIAL PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('network','cctv')), diagram JSONB NOT NULL DEFAULT '{"nodes":[],"edges":[]}', updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS plans_site_idx ON plans(site_id);
CREATE TABLE IF NOT EXISTS equipment (id SERIAL PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites, name TEXT NOT NULL, kind TEXT NOT NULL, ip TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS equipment_site_idx ON equipment(site_id);
CREATE TABLE IF NOT EXISTS uploads (id SERIAL PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites, user_id INTEGER NOT NULL REFERENCES users, original_name TEXT NOT NULL, stored_name TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS uploads_site_idx ON uploads(site_id);
CREATE TABLE IF NOT EXISTS sessions (sid VARCHAR NOT NULL PRIMARY KEY, sess JSON NOT NULL, expire TIMESTAMP(6) NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expire_idx ON sessions(expire);

ALTER TABLE users ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS auth_version INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK(role IN ('superadmin','admin','technician'));
